import{_ as t,o as r,c as o,a1 as s}from"./chunks/framework.DdbKPUhY.js";const v=JSON.parse('{"title":"Server API Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/server-api.md","filePath":"spec/server-api.md"}'),i={name:"spec/server-api.md"};function n(l,e,a,c,d,u){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="server-api-spec" tabindex="-1">Server API Spec <a class="header-anchor" href="#server-api-spec" aria-label="Permalink to &quot;Server API Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Server module manages the HTTP server lifecycle: creation, binding, listening, connection acceptance, and graceful shutdown. It is the top-level object that ties together the event loop, router, TLS context, and WebSocket connection management.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-server-new" tabindex="-1">uvhttp_server_new <a class="header-anchor" href="#uvhttp-server-new" aria-label="Permalink to &quot;uvhttp_server_new&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_new(uv_loop_t* loop, uvhttp_server_t** server)</code></li><li><strong>Purpose</strong>: Create a new HTTP server instance</li><li><strong>Preconditions</strong>: <code>loop</code> must be a valid, initialized <code>uv_loop_t</code>. <code>server</code> must be a non-NULL pointer to a <code>uvhttp_server_t*</code> that will receive the result.</li><li><strong>Postconditions</strong>: On success, <code>*server</code> points to a valid server with <code>is_listening=0</code>, <code>freed=0</code>, <code>active_connections=0</code>, <code>handler=NULL</code>, <code>router=NULL</code>, <code>config=NULL</code>, <code>context=NULL</code>, <code>tls_ctx=NULL</code>.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>loop</code> or <code>server</code> is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe. Must be called from the event loop thread.</li></ul><h3 id="uvhttp-server-listen" tabindex="-1">uvhttp_server_listen <a class="header-anchor" href="#uvhttp-server-listen" aria-label="Permalink to &quot;uvhttp_server_listen&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_listen(uvhttp_server_t* server, const char* host, int port)</code></li><li><strong>Purpose</strong>: Bind to a host:port and start accepting connections</li><li><strong>Preconditions</strong>: <code>server</code> must be valid (created by <code>uvhttp_server_new</code>), not already listening. A handler or router must have been set.</li><li><strong>Postconditions</strong>: On success, <code>server-&gt;is_listening=1</code>, the TCP handle is bound and listening. On failure, server state is unchanged.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>server</code> or <code>host</code> is NULL</li><li><code>UVHTTP_ERROR_SERVER_LISTEN</code>: bind or listen syscall failed</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-server-stop" tabindex="-1">uvhttp_server_stop <a class="header-anchor" href="#uvhttp-server-stop" aria-label="Permalink to &quot;uvhttp_server_stop&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_stop(uvhttp_server_t* server)</code></li><li><strong>Purpose</strong>: Stop accepting new connections. Existing connections continue.</li><li><strong>Preconditions</strong>: <code>server</code> must be listening.</li><li><strong>Postconditions</strong>: <code>server-&gt;is_listening=0</code>. The TCP handle is closed.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>server</code> is NULL</li><li><code>UVHTTP_ERROR_NOT_FOUND</code>: server is not listening</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-server-free" tabindex="-1">uvhttp_server_free <a class="header-anchor" href="#uvhttp-server-free" aria-label="Permalink to &quot;uvhttp_server_free&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_free(uvhttp_server_t* server)</code></li><li><strong>Purpose</strong>: Free all server resources. Must be called after stop.</li><li><strong>Preconditions</strong>: <code>server</code> must be valid. Should not be listening (call <code>stop</code> first).</li><li><strong>Postconditions</strong>: All server memory is freed. The <code>freed</code> flag prevents double-free. Any remaining connections are cleaned up.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>server</code> is NULL</li><li>Double-free is handled gracefully (returns UVHTTP_OK on second call)</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-server-set-handler" tabindex="-1">uvhttp_server_set_handler <a class="header-anchor" href="#uvhttp-server-set-handler" aria-label="Permalink to &quot;uvhttp_server_set_handler&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_set_handler(uvhttp_server_t* server, uvhttp_request_handler_t handler)</code></li><li><strong>Purpose</strong>: Set the default request handler for all requests</li><li><strong>Preconditions</strong>: <code>server</code> must be valid. <code>handler</code> must be non-NULL.</li><li><strong>Postconditions</strong>: <code>server-&gt;handler</code> is set to the provided handler.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>server</code> or <code>handler</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-server-set-router" tabindex="-1">uvhttp_server_set_router <a class="header-anchor" href="#uvhttp-server-set-router" aria-label="Permalink to &quot;uvhttp_server_set_router&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_set_router(uvhttp_server_t* server, uvhttp_router_t* router)</code></li><li><strong>Purpose</strong>: Attach a router for path-based request dispatching</li><li><strong>Preconditions</strong>: <code>server</code> must be valid. <code>router</code> must be a valid router.</li><li><strong>Postconditions</strong>: <code>server-&gt;router</code> is set. The server does not own the router; the caller must free it after the server.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>server</code> or <code>router</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-server-set-context" tabindex="-1">uvhttp_server_set_context <a class="header-anchor" href="#uvhttp-server-set-context" aria-label="Permalink to &quot;uvhttp_server_set_context&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_set_context(uvhttp_server_t* server, struct uvhttp_context* context)</code></li><li><strong>Purpose</strong>: Attach a context object for shared state</li><li><strong>Preconditions</strong>: <code>server</code> must be valid. <code>context</code> must be a valid context.</li><li><strong>Postconditions</strong>: <code>server-&gt;context</code> is set.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>server</code> or <code>context</code> is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-server-enable-tls-uvhttp-server-disable-tls" tabindex="-1">uvhttp_server_enable_tls / uvhttp_server_disable_tls <a class="header-anchor" href="#uvhttp-server-enable-tls-uvhttp-server-disable-tls" aria-label="Permalink to &quot;uvhttp_server_enable_tls / uvhttp_server_disable_tls&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_enable_tls(uvhttp_server_t* server, uvhttp_tls_context_t* tls_ctx)</code> / <code>uvhttp_error_t uvhttp_server_disable_tls(uvhttp_server_t* server)</code></li><li><strong>Purpose</strong>: Enable or disable TLS on the server</li><li><strong>Preconditions</strong>: <code>server</code> must be valid. TLS must be compiled in (<code>UVHTTP_FEATURE_TLS</code>).</li><li><strong>Postconditions</strong>: <code>server-&gt;tls_enabled</code> is set accordingly.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: <code>server</code> is NULL</li><li><code>UVHTTP_ERROR_TLS_INIT</code>: TLS context is invalid</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li><li><strong>Feature gate</strong>: <code>#if UVHTTP_FEATURE_TLS</code></li></ul><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Server-request binding</strong>: Each incoming connection creates a <code>uvhttp_request_t</code> and <code>uvhttp_response_t</code> pair. The handler is called once per request.</p></li><li><p><strong>Handler dispatch priority</strong>: If a router is set, the router is consulted first. If the router finds a matching handler, it is used. Otherwise, the default handler is used.</p></li><li><p><strong>Connection limit</strong>: The server enforces <code>max_connections</code>. When the limit is reached, new connections receive a 503 response.</p></li><li><p><strong>Graceful shutdown</strong>: <code>uvhttp_server_stop</code> stops accepting new connections. Existing connections are allowed to complete. <code>uvhttp_server_free</code> cleans up all resources.</p></li><li><p><strong>Double-free protection</strong>: The <code>freed</code> flag prevents double-free. Calling <code>uvhttp_server_free</code> twice is safe.</p></li><li><p><strong>Rate limiting</strong>: When enabled, the server tracks request count per time window. When the limit is exceeded, new requests receive a 429 response.</p></li></ol><h2 id="performance-requirements" tabindex="-1">Performance Requirements <a class="header-anchor" href="#performance-requirements" aria-label="Permalink to &quot;Performance Requirements&quot;">​</a></h2><ul><li>Connection acceptance: O(1) per new connection</li><li>Handler dispatch: O(1) when router cache is used</li><li>Memory: ~256 bytes per server instance (plus per-connection allocations)</li></ul><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Server creation and destruction (with and without router, config, context)</li><li>Listen on valid and invalid hosts/ports</li><li>Stop and restart</li><li>Multiple server instances on the same loop</li><li>Connection limit enforcement</li><li>Double-free protection</li><li>Rate limiting enable/disable/check</li><li>TLS enable/disable</li><li>WebSocket connection management enable/disable</li><li>Handler dispatch with router and without</li><li>Server configuration via builder API</li></ul>',26)])])}const _=t(i,[["render",n]]);export{v as __pageData,_ as default};
